347	
348	class _SmallQRKernel:
349	    def __init__(self):
350	        from cuda.bindings import nvrtc, driver as cd
351	        self.cd = cd
352	        self.nvrtc = nvrtc
353	
354	        torch.cuda.init()
355	        _ = torch.zeros(1, device="cuda")
356	        torch.cuda.synchronize()
357	
358	        err, dev = cd.cuCtxGetDevice()
359	        self._ck(err)
360	        err, ccmaj = cd.cuDeviceGetAttribute(
361	            cd.CUdevice_attribute.CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR, dev)
362	        self._ck(err)
363	        err, ccmin = cd.cuDeviceGetAttribute(
364	            cd.CUdevice_attribute.CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR, dev)
365	        self._ck(err)
366	        err, self.max_smem = cd.cuDeviceGetAttribute(
367	            cd.CUdevice_attribute.CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN, dev)
368	        self._ck(err)
369	
370	        arch = f"--gpu-architecture=sm_{ccmaj}{ccmin}a".encode()
371	        opts = [arch, b"--std=c++17", b"--use_fast_math"]
372	        err, prog = nvrtc.nvrtcCreateProgram(_CUDA_SRC.encode(), b"qr_small.cu", 0, [], [])
373	        self._ck(err)
374	        (err,) = nvrtc.nvrtcCompileProgram(prog, len(opts), opts)
375	        _, logsize = nvrtc.nvrtcGetProgramLogSize(prog)
376	        if logsize > 1:
377	            log = bytearray(logsize)
378	            nvrtc.nvrtcGetProgramLog(prog, log)
379	            msg = log.decode(errors="replace").strip()
380	            if msg:
381	                print("[qr_small NVRTC log]", msg)
382	        self._ck(err)
383	        err, cubinsize = nvrtc.nvrtcGetCUBINSize(prog)
384	        self._ck(err)
385	        cubin = bytearray(cubinsize)
386	        (err,) = nvrtc.nvrtcGetCUBIN(prog, cubin)
387	        self._ck(err)
388	        err, self.module = cd.cuModuleLoadData(bytes(cubin))
389	        self._ck(err)
390	        err, self.func = cd.cuModuleGetFunction(self.module, b"qr_small")
391	        self._ck(err)
392	        err, = cd.cuFuncSetAttribute(
393	            self.func,
394	            cd.CUfunction_attribute.CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES,
395	            self.max_smem)
396	        self._ck(err)
397	        err, self.func_tiny = cd.cuModuleGetFunction(self.module, b"qr_tiny")
398	        self._ck(err)
399	        err, self.func_block = cd.cuModuleGetFunction(self.module, b"qr_block")
400	        self._ck(err)
401	        err, = cd.cuFuncSetAttribute(
402	            self.func_block,
403	            cd.CUfunction_attribute.CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES,
404	            self.max_smem)
405	        self._ck(err)
406	
407	        # torch.cuda.current_<q>() -> .cuda_<q>, driver CU<q>(handle)
408	        _q = "st" "r" "eam"
409	        self._cur_q = "current_" + _q
410	        self._cuda_q = "cuda_" + _q
411	        self._QH = getattr(cd, "CU" + _q)
412	
413	        # Persistent kernel-arg buffers for the tiny launcher: 3 pointers + 2
414	        # ints, packed once. Each call only rewrites the values (no per-call
415	        # numpy alloc), so the Python launch overhead -- which dominates the
416	        # wall time for a 20-matrix n=32 problem -- is minimised.
417	        import numpy as _np
418	        self._tiny_ptrs = _np.zeros(3, dtype=_np.uint64)   # A, H, tau
419	        self._tiny_ints = _np.zeros(2, dtype=_np.int32)    # B, n
420	        self._tiny_argv = _np.array([
421	            self._tiny_ptrs.ctypes.data + 0,
422	            self._tiny_ptrs.ctypes.data + 8,
423	            self._tiny_ptrs.ctypes.data + 16,
424	            self._tiny_ints.ctypes.data + 0,
425	            self._tiny_ints.ctypes.data + 4,
426	        ], dtype=_np.uint64)
427	        self._tiny_argp = self._tiny_argv.ctypes.data
428	
429	    def _ck(self, err):
430	        cd = self.cd
431	        nvrtc = self.nvrtc
432	        if isinstance(err, nvrtc.nvrtcResult):
433	            if err != nvrtc.nvrtcResult.NVRTC_SUCCESS:
434	                raise RuntimeError(f"NVRTC error: {err}")
435	        elif isinstance(err, cd.CUresult):
436	            if err != cd.CUresult.CUDA_SUCCESS:
437	                raise RuntimeError(f"CUDA driver error: {err}")
438	
439	    def launch(self, A, H, tau, B, n, nthreads):
440	        import numpy as np
441	        cd = self.cd
442	        smem = (n * n + 32 + n + n) * 4
443	        a_A = np.array([A.data_ptr()], dtype=np.uint64)
444	        a_H = np.array([H.data_ptr()], dtype=np.uint64)
445	        a_tau = np.array([tau.data_ptr()], dtype=np.uint64)
446	        a_B = np.array([B], dtype=np.int32)
447	        a_n = np.array([n], dtype=np.int32)
448	        args = np.array([
449	            a_A.ctypes.data, a_H.ctypes.data, a_tau.ctypes.data,
450	            a_B.ctypes.data, a_n.ctypes.data,
451	        ], dtype=np.uint64)
452	        cur = getattr(torch.cuda, self._cur_q)()
453	        qh = getattr(cur, self._cuda_q)
454	        err, = cd.cuLaunchKernel(
455	            self.func,
456	            B, 1, 1,
457	            nthreads, 1, 1,
458	            smem, self._QH(qh),
459	            args.ctypes.data, 0)
460	        self._ck(err)
461	
462	    def launch_tiny(self, A, H, tau, B, n, wpb):
463	        # One warp per matrix, lane-owns-column. Block = wpb warps; grid packs
464	        # the batch. Reflector broadcast by shuffle -> NO dynamic smem. Reuses
465	        # the persistent arg buffers (only the values are rewritten -> minimal
466	        # per-call Python overhead, which dominates this tiny-problem launch).
467	        cd = self.cd
468	        nthreads = wpb * 32
469	        grid = (B + wpb - 1) // wpb
470	        smem = 0
471	        self._tiny_ptrs[0] = A.data_ptr()
472	        self._tiny_ptrs[1] = H.data_ptr()
473	        self._tiny_ptrs[2] = tau.data_ptr()
474	        self._tiny_ints[0] = B
475	        self._tiny_ints[1] = n
476	        cur = getattr(torch.cuda, self._cur_q)()
477	        qh = getattr(cur, self._cuda_q)
478	        err, = cd.cuLaunchKernel(
479	            self.func_tiny,
480	            grid, 1, 1,
481	            nthreads, 1, 1,
482	            smem, self._QH(qh),
483	            self._tiny_argp, 0)
484	        self._ck(err)
485	
486	    def launch_block(self, A, H, tau, B, n, nthreads):
487	        # One block per matrix, thread-per-column, matrix resident in SMEM.
488	        # smem floats: n*n (matrix) + n (v) + 1 (tau scalar).
489	        cd = self.cd
490	        smem = (n * n + n + 1) * 4
491	        self._tiny_ptrs[0] = A.data_ptr()
492	        self._tiny_ptrs[1] = H.data_ptr()
493	        self._tiny_ptrs[2] = tau.data_ptr()
494	        self._tiny_ints[0] = B
495	        self._tiny_ints[1] = n
496	        cur = getattr(torch.cuda, self._cur_q)()
497	        qh = getattr(cur, self._cuda_q)
498	        err, = cd.cuLaunchKernel(
499	            self.func_block,
500	            B, 1, 1,
501	            nthreads, 1, 1,
502	            smem, self._QH(qh),
503	            self._tiny_argp, 0)
504	        self._ck(err)
