510	def _get_kernel():
511	    global _KERNEL
512	    if _KERNEL is None:
513	        _KERNEL = _SmallQRKernel()
514	    return _KERNEL
515	
516	
517	def _small_qr(A):
518	    B, n, _ = A.shape
519	    kern = _get_kernel()
520	    # smem budget (floats): n*n + 32 (warp scratch) + n (v)
521	    H = torch.empty((B, n, n), device=A.device, dtype=torch.float32)
522	    tau = torch.zeros((B, n), device=A.device, dtype=torch.float32)
523	    # Enough threads to parallelize the 2D trailing tile; capped at 1024.
524	    if n <= 32:
525	        nthreads = 32
526	    elif n <= 64:
527	        nthreads = 128
528	    else:
529	        nthreads = 512
530	    kern.launch(A.contiguous(), H, tau, B, n, nthreads)
531	    return H, tau
532	
