534	# Warps-per-block for qr_tiny. Micro-swept on n=32,B=20: fewer warps/block =>
535	# matrices spread across MORE SMs => less serial-chain contention per SM. wpb=2
536	# (51.3us) ~ wpb=1 (51.4us) << wpb=8 (57us) << wpb=20 (92us, all on 1 SM).
537	import os as _os
538	_TINY_WPB = int(_os.environ.get("QR_TINY_WPB", "2"))
539	
540	
541	def _tiny_qr(A):
542	    B, n, _ = A.shape
543	    kern = _get_kernel()
544	    H = torch.empty((B, n, n), device=A.device, dtype=torch.float32)
545	    # The kernel writes taub[k] for every k=0..n-1, so no pre-zeroing memset.
546	    tau = torch.empty((B, n), device=A.device, dtype=torch.float32)
547	    kern.launch_tiny(A.contiguous(), H, tau, B, n, _TINY_WPB)
548	    return H, tau
