551	def _block_qr(A):
552	    B, n, _ = A.shape
553	    kern = _get_kernel()
554	    H = torch.empty((B, n, n), device=A.device, dtype=torch.float32)
555	    tau = torch.zeros((B, n), device=A.device, dtype=torch.float32)
556	    nthreads = ((n + 31) // 32) * 32     # one thread per column, warp-rounded
557	    kern.launch_block(A.contiguous(), H, tau, B, n, nthreads)
558	    return H, tau
