562	# Large-n backend: batch-MAJOR right-looking blocked Householder QR (Triton).
563	# Used for the larger shapes (n > 256) where the batch fills the grid and a
564	# BLAS-3 trailing update dominates. The small/medium shapes (n <= 256) instead
565	# use the fused one-block-per-matrix on-chip kernel above. Kept geqrf-exact;
566	# imported intact from the in-run batch-major line.
567	# =============================================================================
568	@triton.jit
569	def _panel_factor_kernel(
570	    A_ptr, tau_ptr, Vbuf_ptr, Tbuf_ptr,
571	    B, N, j, pheight, b,
572	    stride_ab, stride_an,
573	    stride_vb, stride_vk, stride_vn,
574	    stride_tb, stride_tk, stride_tn,
575	    BLK: tl.constexpr, MAXH: tl.constexpr,
576	):
577	    bid = tl.program_id(0)
578	    if bid >= B:
579	        return
580	
581	    rows = tl.arange(0, MAXH)                 # relative to panel top (global row j)
582	    cols = tl.arange(0, BLK)
583	    row_valid = rows < pheight
584	    col_valid = cols < b
585	
586	    a_base = A_ptr + bid * stride_ab + j * stride_an + j
587	    aptr = a_base + rows[:, None] * stride_an + cols[None, :]
588	    mask = row_valid[:, None] & col_valid[None, :]
589	    panel = tl.load(aptr, mask=mask, other=0.0)          # (MAXH, BLK)
590	
591	    tau_panel = tl.zeros((BLK,), dtype=tl.float32)
592	    # Build the WY T factor (BLK x BLK upper-tri) incrementally here (LAPACK
593	    # dlarft forward): at step k, T[0:k,k] = -tau_k * T[0:k,0:k] * (V[:,0:k]^T v_k).
594	    # This fuses build_T into panel_factor, eliminating a whole low-occupancy
595	    # kernel launch + a re-read of V from HBM.
596	    Tmat = tl.zeros((BLK, BLK), dtype=tl.float32)
597	
598	    for k in range(0, BLK):
599	        do_k = k < b
600	        col_is_k = cols == k
601	        xk = tl.sum(tl.where(col_is_k[None, :], panel, 0.0), axis=1)   # (MAXH,)
602	        active = (rows >= k) & row_valid
603	        xk = tl.where(active, xk, 0.0)
604	
605	        alpha = tl.sum(tl.where(rows == k, xk, 0.0))
606	        tailv = tl.where(rows > k, xk, 0.0)
607	        tail_n2 = tl.sum(tailv * tailv)
608	        normx = tl.sqrt(alpha * alpha + tail_n2)
609	        sgn = tl.where(alpha >= 0.0, 1.0, -1.0)
610	        beta = -sgn * normx
611	        has_refl = tail_n2 > 0.0
612	        beta_safe = tl.where(beta == 0.0, 1.0, beta)
613	        tau_k = tl.where(has_refl, (beta - alpha) / beta_safe, 0.0)
614	
615	        denom = alpha - beta
616	        denom = tl.where(denom == 0.0, 1.0, denom)
617	        v = tl.where(rows > k, xk / denom, 0.0)
618	        v = tl.where(rows == k, 1.0, v)
619	        v = tl.where(active, v, 0.0)
620	        v = tl.where(has_refl, v, tl.where(rows == k, 1.0, 0.0))
621	
622	        # w[c] = v_k . panel[:,c] -- used both for the trailing-panel update AND
623	        # the incremental T factor. Because v_k is supported only on rows >= k,
624	        # for c < k we have z[c] = V[:,c].v_k == w[c] exactly (the diagonal/above
625	        # terms vanish), so the WY recurrence needs no separate (MAXH,BLK) Vmat
626	        # tensor or extra reduction -- a big register/occupancy win on the panel.
627	        w = tl.sum(v[:, None] * panel, axis=0)            # (BLK,)
628	
629	        # --- incremental T column k:  T[a<k,k] = -tau_k * (T @ w[c<k]) ---
630	        z = tl.where(cols < k, w, 0.0)
631	        Tcol = -tau_k * tl.sum(Tmat * z[None, :], axis=1)  # (BLK,)
632	        Tcol = tl.where(cols < k, Tcol, 0.0)
633	        Tcol = tl.where(cols == k, tau_k, Tcol)
634	        Tmat = tl.where(col_is_k[None, :], Tcol[:, None], Tmat)
635	
636	        # apply H_k to trailing panel columns (c > k)
637	        upd = tau_k * v[:, None] * w[None, :]
638	        col_gt_k = cols > k
639	        panel = tl.where(col_gt_k[None, :], panel - upd, panel)
640	
641	        # store this column: R[k,k] on diag, reflector below; leave rows<k
642	        # (already-finalized R entries from earlier steps) untouched.
643	        diagval = tl.where(has_refl, beta, alpha)
644	        new_colk = tl.where(rows == k, diagval, v)        # row==k -> beta, row>k -> v
645	        panel = tl.where(col_is_k[None, :] & (rows[:, None] >= k), new_colk[:, None], panel)
646	
647	        tau_panel = tl.where(col_is_k & do_k, tau_k, tau_panel)
648	
649	    tl.store(aptr, panel, mask=mask)
650	
651	    tptr = tau_ptr + bid * N + j + cols
652	    tl.store(tptr, tau_panel, mask=col_valid)
653	
654	    # V transposed: Vt[c, r] = 1 if r==c, panel[r,c] if r>c, else 0
655	    panelT = tl.trans(panel)                               # (BLK, MAXH)
656	    cc = cols[:, None]
657	    rr = rows[None, :]
658	    Vt = tl.where(rr == cc, 1.0, tl.where(rr > cc, panelT, 0.0))
659	    Vt = tl.where((rr < pheight) & (cc < b), Vt, 0.0)
660	    vbase = Vbuf_ptr + bid * stride_vb
661	    vptr = vbase + cc * stride_vk + rr * stride_vn
662	    tl.store(vptr, Vt, mask=(rr < pheight) & (cc < b))
663	
664	    # store T
665	    tbase = Tbuf_ptr + bid * stride_tb
666	    tptr2 = tbase + cols[:, None] * stride_tk + cols[None, :] * stride_tn
667	    tl.store(tptr2, Tmat)
668	
669	
670	# Trailing update is split into TWO kernels to be race-free: the first reads
671	# A_trail and produces YT = T^T V^T A_trail (read-only consumer of A_trail); the
672	# second reads YT (read-only) and applies A_trail -= V @ YT (each program owns a
673	# disjoint output tile). Fusing them (one kernel that both reads all rows of a
674	# column and writes its own row slice) races: program for row-tile r0 reads rows
675	# owned by row-tile r1 while r1 writes them.
676	@triton.jit
677	def _trailing_YT_kernel(
678	    A_ptr, Vbuf_ptr, Tbuf_ptr, YT_ptr,
679	    B, N, j, pheight, ncols, jb,
680	    stride_ab, stride_an,
681	    stride_vb, stride_vk, stride_vn,
682	    stride_tb, stride_tk, stride_tn,
683	    stride_yb, stride_yk, stride_yn,
684	    BLK: tl.constexpr, BM: tl.constexpr, BNc: tl.constexpr,
685	):
686	    col_tile = tl.program_id(0)
687	    bid = tl.program_id(1)
688	    if bid >= B:
689	        return
690	    c0 = col_tile * BNc
691	    ccols = c0 + tl.arange(0, BNc)
692	    cmask = ccols < ncols
693	    krange = tl.arange(0, BLK)
694	
695	    a_trail_base = A_ptr + bid * stride_ab + j * stride_an + jb
696	    v_base = Vbuf_ptr + bid * stride_vb
697	
698	    # W = V^T @ A_trail over all panel rows, in chunks of BM
699	    W = tl.zeros((BLK, BNc), dtype=tl.float32)
700	    nchunks = tl.cdiv(pheight, BM)
701	    for ci in range(0, nchunks):
702	        rr = ci * BM + tl.arange(0, BM)
703	        rrmask = rr < pheight
704	        ap = a_trail_base + rr[:, None] * stride_an + ccols[None, :]
705	        achunk = tl.load(ap, mask=rrmask[:, None] & cmask[None, :], other=0.0)   # (BM,BNc)
706	        vp = v_base + krange[:, None] * stride_vk + rr[None, :] * stride_vn
707	        vchunk = tl.load(vp, mask=rrmask[None, :], other=0.0)                    # (BLK,BM)
708	        W += tl.dot(vchunk, achunk, input_precision="tf32x3")
709	
710	    # YT = T^T @ W
711	    tp = Tbuf_ptr + bid * stride_tb + krange[:, None] * stride_tk + krange[None, :] * stride_tn
712	    Tm = tl.load(tp)
713	    YT = tl.dot(tl.trans(Tm), W, input_precision="tf32x3")                        # (BLK,BNc)
714	
715	    yp = YT_ptr + bid * stride_yb + krange[:, None] * stride_yk + ccols[None, :] * stride_yn
716	    tl.store(yp, YT, mask=cmask[None, :])
717	
718	
719	@triton.jit
720	def _trailing_apply_kernel(
721	    A_ptr, Vbuf_ptr, YT_ptr,
722	    B, N, j, pheight, ncols, jb,
723	    stride_ab, stride_an,
724	    stride_vb, stride_vk, stride_vn,
725	    stride_yb, stride_yk, stride_yn,
726	    BLK: tl.constexpr, BM: tl.constexpr, BNc: tl.constexpr,
727	):
728	    pid = tl.program_id(0)
729	    bid = tl.program_id(1)
730	    if bid >= B:
731	        return
732	    num_col_tiles = tl.cdiv(ncols, BNc)
733	    row_tile = pid // num_col_tiles
734	    col_tile = pid % num_col_tiles
735	    rrows = row_tile * BM + tl.arange(0, BM)
736	    ccols = col_tile * BNc + tl.arange(0, BNc)
737	    rmask = rrows < pheight
738	    cmask = ccols < ncols
739	    krange = tl.arange(0, BLK)
740	
741	    a_trail_base = A_ptr + bid * stride_ab + j * stride_an + jb
742	    v_base = Vbuf_ptr + bid * stride_vb
743	
744	    # V[rrows,:] : (BM, BLK)
745	    vp = v_base + krange[None, :] * stride_vk + rrows[:, None] * stride_vn
746	    Vrow = tl.load(vp, mask=rmask[:, None], other=0.0)
747	    # YT[:, ccols] : (BLK, BNc)
748	    yp = YT_ptr + bid * stride_yb + krange[:, None] * stride_yk + ccols[None, :] * stride_yn
749	    YT = tl.load(yp, mask=cmask[None, :], other=0.0)
750	    delta = tl.dot(Vrow, YT, input_precision="tf32x3")                            # (BM,BNc)
751	
752	    ap = a_trail_base + rrows[:, None] * stride_an + ccols[None, :]
753	    amask = rmask[:, None] & cmask[None, :]
754	    aorig = tl.load(ap, mask=amask, other=0.0)
755	    tl.store(ap, aorig - delta, mask=amask)
756	
